// =========================== CONFIG ===========================
const JOB = {
  title: "Senior n8n / Automation Engineer",
  mustHaveSkills: ["n8n", "API integration", "JavaScript", "workflow automation"],
  niceToHaveSkills: ["Python", "Notion API", "OpenAI API", "Zapier/Make experience"],
  minExperienceYears: 2,
  description: "We're hiring an automation engineer to design, build and maintain n8n workflows that connect our CRM, support, and finance tools. Strong API integration and JavaScript skills required."
};
const SHORTLIST_THRESHOLD = 75;   // score out of 100
const RECRUITER_EMAIL = "recruiter@yourcompany.com";
// ================================================================

const j = $input.item.json.body || $input.item.json;
const required = ["name", "email", "resumeText"];
const missing = required.filter(k => !j[k]);
if (missing.length) throw new Error("Missing required application fields: " + missing.join(", "));

const system = `You are a resume screener. Compare the candidate's resume against the job requirements and return ONLY valid JSON with this exact shape:
{
  "candidate_name": "string",
  "total_experience_years": number,
  "key_skills_matched": ["..."],
  "key_skills_missing": ["..."],
  "education_summary": "one line",
  "score": number (0-100, weighted toward must-have skills and minimum experience),
  "recommendation": "Shortlist" | "Review",
  "summary": "2-3 sentence objective summary of fit, no opinions on the person, only on qualifications"
}
Rules: base every field strictly on the resume text provided. Never invent experience, skills, or credentials not present in the text. If information is missing from the resume, note it as missing rather than guessing. Score conservatively when evidence is thin. "recommendation" is "Shortlist" only if score >= ${SHORTLIST_THRESHOLD} AND all must-have skills are present or clearly transferable; otherwise "Review".`;

const userMsg = `Job: ${JOB.title}
Description: ${JOB.description}
Must-have skills: ${JOB.mustHaveSkills.join(", ")}
Nice-to-have skills: ${JOB.niceToHaveSkills.join(", ")}
Minimum experience: ${JOB.minExperienceYears} years

Candidate name (from form): ${j.name}
Candidate email (from form): ${j.email}
Candidate phone (from form): ${j.phone || "not provided"}
Role applied for: ${j.roleAppliedFor || JOB.title}

Resume text:
${j.resumeText.slice(0, 20000)}`;

const aiRequest = {
  model: "gpt-4o-mini",
  temperature: 0.1,
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: system },
    { role: "user", content: userMsg }
  ]
};

return { json: {
  aiRequest,
  meta: {
    formName: j.name, formEmail: j.email, formPhone: j.phone || "",
    roleAppliedFor: j.roleAppliedFor || JOB.title,
    resumeUrl: j.resumeUrl || "",
    appliedDate: new Date().toISOString().slice(0, 10),
    shortlistThreshold: SHORTLIST_THRESHOLD,
    recruiterEmail: RECRUITER_EMAIL,
    jobTitle: JOB.title
  }
}};

const res = $input.first().json;
const meta = $('Prepare Screening Prompt').first().json.meta;
let data;
try { data = JSON.parse(res.choices[0].message.content); }
catch (e) { throw new Error('AI returned invalid JSON: ' + e.message); }

const score = Math.max(0, Math.min(100, Number(data.score) || 0));
const shortlisted = score >= meta.shortlistThreshold && data.recommendation === "Shortlist";

return [{ json: {
  name: data.candidate_name || meta.formName,
  email: meta.formEmail,
  phone: meta.formPhone,
  roleAppliedFor: meta.roleAppliedFor,
  experienceYears: Number(data.total_experience_years) || 0,
  skillsMatched: (data.key_skills_matched || []).join(", "),
  skillsMissing: (data.key_skills_missing || []).join(", "),
  education: data.education_summary || "",
  score,
  recommendation: shortlisted ? "Shortlist" : "Review",
  shortlisted,
  summary: data.summary || "",
  resumeUrl: meta.resumeUrl,
  appliedDate: meta.appliedDate,
  jobTitle: meta.jobTitle,
  recruiterEmail: meta.recruiterEmail
}}];

const c = $('Parse Candidate Score').item.json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
<p>Hi ${esc(c.name)},</p>
<p>Thank you for applying for <b>${esc(c.jobTitle)}</b> — your background looks like a strong match, and we'd love to talk further.</p>
<p>Please use this link to book a 30-minute interview slot at a time that works for you: <a href="REPLACE_WITH_SCHEDULING_LINK">Schedule your interview</a></p>
<p>Looking forward to speaking with you.</p>
<p>Best,<br>Hiring Team</p>
</div>`;
return [{ json: { to: c.email, subject: `Next step: interview for ${c.jobTitle}`, html } }];

